      case 'ArrowDown':
        event.preventDefault();
        this.selectNext();
        return true;

      case 'ArrowUp':
        event.preventDefault();
        this.selectPrevious();
        return true;

      case 'Enter':
      case 'Tab':
        event.preventDefault();
        this.selectCurrent();
        return true;

      case 'Escape':
        event.preventDefault();
        this.options.onClose();
        return true;

      default:
        return false;
    }
  }

