  'before',
  'after',
  'placeholder',
  'file',
  'marker',
  'selection',
  'first-line',
  'first-letter',
  'backdrop',

  // Responsive variants
  'sm',
  'md',
  'lg',
  'xl',
  '2xl',

  // Dark mode
  'dark',

  // Group/peer variants
  'group-hover',
  'group-focus',
  'group-active',
  'group-visited',
  'peer-hover',
  'peer-focus',
  'peer-checked',
  'peer-disabled',

  // Child variants
  'first',
