      if (results.length > 0) {
        this.showDropdown(results);
      } else {
        console.log('[UX Builder TW] No results found');
        this.hideDropdown();
      }
    } catch (error) {
      console.warn('[UX Builder TW] Search failed:', error);
      this.hideDropdown();
    }
  }

