    this.input.removeEventListener('blur', this.handleBlur);
    this.input.removeEventListener('focus', this.handleFocus);

    if (this.debounceTimer !== null) {
      window.clearTimeout(this.debounceTimer);
    }

    this.hideDropdown();
  }
