  // State variants
  'hover',
  'focus',
  'active',
  'visited',
  'focus-within',
  'focus-visible',
  'disabled',
  'enabled',
  'checked',
  'indeterminate',
  'default',
  'required',
  'valid',
  'invalid',
  'in-range',
  'out-of-range',
  'placeholder-shown',
  'autofill',
  'read-only',

  // Pseudo-element variants
  'before',
  'after',
  'placeholder',
  'file',
  'marker',
  'selection',
  'first-line',
  'first-letter',
  'backdrop',

  // Responsive variants
  'sm',
  'md',
  'lg',
  'xl',
  '2xl',

  // Dark mode
  'dark',

  // Group/peer variants
  'group-hover',
  'group-focus',
  'group-active',
  'group-visited',
  'peer-hover',
  'peer-focus',
  'peer-checked',
  'peer-disabled',

