  if (top + panelHeight > window.innerHeight + scrollTop) {
    top = window.innerHeight + scrollTop - panelHeight - 20;
  }

  // Ensure panel doesn't go above viewport
  if (top < scrollTop) {
    top = scrollTop + 20;
  }

  return { top, left };
